#include "stdlib/blas/ext/base/dsort2ins.h"
#include "stdlib/math/base/assert/is_negative_zero.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdbool.h>

/**
* Simultaneously sorts two double-precision floating-point strided arrays based on the sort order of the first array using insertion sort.
*
* @param N        number of indexed elements
* @param order    sort order
* @param X        first input array
* @param strideX  `X` stride length
* @param Y        second input array
* @param strideY  `Y` stride length
*/
void API_SUFFIX(stdlib_strided_dsort2ins)( const CBLAS_INT N, const CBLAS_INT order, double *X, CBLAS_INT strideX, double *Y, CBLAS_INT strideY ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	CBLAS_INT oy = stdlib_strided_stride2offset( N, strideY );
	API_SUFFIX(stdlib_strided_dsort2ins_ndarray)( N, order, X, strideX, ox, Y, strideY, oy );
}

/**
* Simultaneously sorts two double-precision floating-point strided arrays based on the sort order of the first array using insertion sort and alternative indexing semantics.
*
* @param N        number of indexed elements
* @param order    sort order
* @param X        first input array
* @param strideX  `X` stride length
* @param offsetX  `X` starting index
* @param Y        second input array
* @param strideY  `Y` stride length
* @param offsetY  `Y` starting index
*/
void API_SUFFIX(stdlib_strided_dsort2ins_ndarray)( const CBLAS_INT N, const CBLAS_INT order, double *X, CBLAS_INT strideX, CBLAS_INT offsetX, double *Y, CBLAS_INT strideY, CBLAS_INT offsetY ) {
	CBLAS_INT ix;
	CBLAS_INT jx;
	CBLAS_INT fx;
	CBLAS_INT lx;
	CBLAS_INT iy;
	CBLAS_INT jy;
	CBLAS_INT fy;
	CBLAS_INT ly;
	CBLAS_INT i;
	double vx;
	double vy;
	double ux;
	bool flg;

	if ( N <= 0 || order == 0.0 ) {
		return;
	}
	// For a positive stride, sorting in decreasing order is equivalent to providing a negative stride and sorting in increasing order, and, for a negative stride, sorting in decreasing order is equivalent to providing a positive stride and sorting in increasing order...
	if ( order < 0.0 ) {
		strideX *= -1;
		strideY *= -1;
		offsetX -= (N-1) * strideX;
		offsetY -= (N-1) * strideY;
	}
	fx = offsetX;
	lx = fx + ((N-1)*strideX);
	ix = fx + strideX;

	fy = offsetY;
	ly = fy + ((N-1)*strideY);
	iy = fy + strideY;

	if ( strideX < 0 ) {
		// Traverse the strided array from right-to-left...

		// Sort in increasing order...
		for ( i = 1; i < N; i++ ) {
			vx = X[ ix ];
			vy = Y[ iy ];

			// Sort `NaN` values to the end (i.e., the left)...
			if ( stdlib_base_is_nan( vx ) ) {
				jx = ix;
				jy = iy;

				// Shift all values (including NaNs) to the left of the current element to the right...
				while ( jx > lx ) {
					X[ jx ] = X[ jx+strideX ];
					Y[ jy ] = Y[ jy+strideY ];
					jx += strideX;
					jy += strideY;
				}
				X[ lx ] = vx;
				Y[ ly ] = vy;
			} else {
				flg = stdlib_base_is_negative_zero( vx );
				jx = ix - strideX;
				jy = iy - strideY;

				// Shift all larger values to the right of the current element to the left...
				while ( jx <= fx ) {
					ux = X[ jx ];
					if ( ux <= vx && !(flg && ux == vx && !stdlib_base_is_negative_zero( ux )) ) {
						// Note: positive zeros (and NaNs (e.g., when last element is NaN)) are sorted to the left
						break;
					}
					X[ jx+strideX ] = ux;
					Y[ jy+strideY ] = Y[ jy ];
					jx -= strideX;
					jy -= strideY;
				}
				X[ jx+strideX ] = vx;
				Y[ jy+strideY ] = vy;
				ix += strideX;
				iy += strideY;
			}
		}
		return;
	}
	// Traverse the strided array from left-to-right...

	// Sort in increasing order...
	for ( i = 1; i < N; i++ ) {
		vx = X[ ix ];
		vy = Y[ iy ];

		// Sort `NaN` values to the end...
		if ( stdlib_base_is_nan( vx ) ) {
			jx = ix;
			jy = iy;

			// Shift all values (including NaNs) to the right of the current element to the left...
			while ( jx < lx ) {
				X[ jx ] = X[ jx+strideX ];
				Y[ jy ] = Y[ jy+strideY ];
				jx += strideX;
				jy += strideY;
			}
			X[ lx ] = vx;
			Y[ ly ] = vy;
		} else {
			flg = stdlib_base_is_negative_zero( vx );
			jx = ix - strideX;
			jy = iy - strideY;

			// Shift all larger values to the left of the current element to the right...
			while ( jx >= fx ) {
				ux = X[ jx ];
				if ( ux <= vx && !(flg && ux == vx && !stdlib_base_is_negative_zero( ux )) ) {
					// Note: positive zeros (and NaNs (e.g., when first element is NaN)) are sorted to the right
					break;
				}
				X[ jx+strideX ] = ux;
				Y[ jy+strideY ] = Y[ jy ];
				jx -= strideX;
				jy -= strideY;
			}
			X[ jx+strideX ] = vx;
			Y[ jy+strideY ] = vy;
			ix += strideX;
			iy += strideY;
		}
	}
	return;
}
